// RemoveSessionClassMedia relationships from objects passed in.
// Removes related items from R.SessionClassMedia (uses pointer comparison, removal does not keep order)
// Sets related.R.Session.
func (o *LMSSession) RemoveSessionClassMedia(exec boil.Executor, related ...*ClassMedium) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.SessionID, nil)
		if rel.R != nil {
			rel.R.Session = nil
		}
		if _, err = rel.Update(exec, boil.Whitelist("session_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.SessionClassMedia {
			if rel != ri {
				continue
			}

			ln := len(o.R.SessionClassMedia)
			if ln > 1 && i < ln-1 {
				o.R.SessionClassMedia[i] = o.R.SessionClassMedia[ln-1]
			}
			o.R.SessionClassMedia = o.R.SessionClassMedia[:ln-1]
			break
		}
	}

	return nil
}

